import{_ as a,o as n,c as e,a5 as i}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"Spec — Landing lab: 17 app thay thế","description":"","frontmatter":{},"headers":[],"relativePath":"feature/landing-lab-replaced-apps/spec.md","filePath":"feature/landing-lab-replaced-apps/spec.md"}'),o={name:"feature/landing-lab-replaced-apps/spec.md"};function r(c,t,h,d,l,p){return n(),e("div",null,[...t[0]||(t[0]=[i('<h1 id="spec-—-landing-lab-17-app-thay-the" tabindex="-1">Spec — Landing lab: 17 app thay thế <a class="header-anchor" href="#spec-—-landing-lab-17-app-thay-the" aria-label="Permalink to &quot;Spec — Landing lab: 17 app thay thế&quot;">​</a></h1><h2 id="objective" tabindex="-1">Objective <a class="header-anchor" href="#objective" aria-label="Permalink to &quot;Objective&quot;">​</a></h2><p>Màn MacBook/iPhone mô phỏng trên landing (<code>CinematicHero</code>) phải cho người xem thấy rõ BrandHub thay được những công cụ nào, theo đúng luồng làm việc của agency. Hiện tại mỗi trang gắn 2-3 chip app nhưng bấm chip nào cũng ra cùng một màn, và vài mô tả nói quá so với sản phẩm.</p><h2 id="user-story" tabindex="-1">User Story <a class="header-anchor" href="#user-story" aria-label="Permalink to &quot;User Story&quot;">​</a></h2><p>Là khách truy cập landing, tôi muốn bấm vào một công cụ quen thuộc (Buffer, Asana, Canva…) và thấy ngay màn BrandHub làm việc đó, kèm 1-2 điểm BrandHub làm tốt hơn, để tin rằng một gói BrandHub thay được nhiều app rời.</p><h2 id="cau-truc-đa-chot-voi-user-2026-11-22" tabindex="-1">Cấu trúc (đã chốt với user 2026-11-22) <a class="header-anchor" href="#cau-truc-đa-chot-voi-user-2026-11-22" aria-label="Permalink to &quot;Cấu trúc (đã chốt với user 2026-11-22)&quot;">​</a></h2><p>Sidebar = 8 giai đoạn theo luồng sản phẩm; mỗi app là một tab riêng (17 tab + Tổng quan).</p><table tabindex="0"><thead><tr><th>Giai đoạn</th><th>Tab → app thay thế</th><th>Tính năng thật trong web</th></tr></thead><tbody><tr><td>Tổng quan</td><td>overview</td><td>dashboard, ma trận &quot;17 app → 1&quot;</td></tr><tr><td>Brief</td><td>typeform · notion</td><td>public-survey (7 loại câu hỏi) · content-writing</td></tr><tr><td>Kế hoạch</td><td>asana · jira</td><td>campaign timeline Gantt · tasks Kanban (task type, subtask role)</td></tr><tr><td>Sáng tạo AI</td><td>jasper · canva · capcut</td><td>AI caption/hashtag theo kênh · AIImageStudioPanel + templates · product-video / video-space</td></tr><tr><td>Tài sản &amp; Team</td><td>drive · brandfolder · slack</td><td>library (folder, version, thùng rác) · client profile + knowledge base · chat realtime</td></tr><tr><td>Duyệt</td><td>frameio</td><td>task-approvals nhiều cấp, client portal</td></tr><tr><td>Xuất bản</td><td>buffer · hootsuite · mailchimp</td><td>lịch đăng FB/IG/TikTok/Threads · social-accounts + bình luận theo bài · mail-templates (khối, gửi theo đợt, hủy đăng ký)</td></tr><tr><td>Đo lường</td><td>sprout · buzzsumo · sheets</td><td>publish dashboard · workspace-trends · reports + XLSX + báo cáo định kỳ</td></tr></tbody></table><h2 id="acceptance-criteria" tabindex="-1">Acceptance Criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance Criteria&quot;">​</a></h2><ol><li>Mỗi tab có màn riêng, nội dung khác nhau, mô phỏng đúng tính năng có thật (cột phải).</li><li>Không mô phỏng tính năng chưa có: không gọi thoại, không hộp thư hợp nhất, không timeline cắt ghép video, không Livestream, không nền tảng ngoài 4 kênh, không cổng thanh toán khác SePay.</li><li>Đầu mỗi màn app có banner &quot;Thay cho &lt;App&gt;&quot; + 2 điểm khác biệt. Không ghi giá đối thủ.</li><li>Dưới banner có dải tab các app cùng giai đoạn để chuyển qua lại.</li><li>Bấm icon app trên Dock → mở đúng tab. Bấm mục sidebar → tab đầu của giai đoạn.</li><li>Tour tự chạy (menu Apple &quot;Xem lại tour&quot;) đi lần lượt 17 tab rồi về Tổng quan.</li><li>Vai trò mặc định: Owner → Tổng quan, Manager → Kế hoạch, Creator → Sáng tạo AI, Client → Duyệt.</li><li>Các section ngoài (Features, HowItWorks, AIFeatures, AgencyWorkspace, Templates) mở đúng tab.</li><li>Mọi màn hiển thị gọn trong cả khung MacBook và iPhone (container query, không tràn ngang).</li><li>Thanh URL hiện <code>brandhub.id.vn/dashboard/&lt;slug của tab&gt;</code>.</li></ol><h2 id="ui-ux" tabindex="-1">UI/UX <a class="header-anchor" href="#ui-ux" aria-label="Permalink to &quot;UI/UX&quot;">​</a></h2><ul><li>Giữ toàn bộ chrome macOS/Safari/Dock hiện có. Chỉ thay nội dung cửa sổ app.</li><li>Màu thương hiệu cam <code>#F05A28</code>, khung app nền sáng như hiện tại.</li><li>Icon dùng <code>lucide-react</code>; logo app đối thủ là glyph SVG trong <code>replacedApps.tsx</code>.</li></ul><h2 id="i18n" tabindex="-1">i18n <a class="header-anchor" href="#i18n" aria-label="Permalink to &quot;i18n&quot;">​</a></h2><ul><li>Namespace mới <code>landingLab</code> (<code>src/i18n/locales/{vi,en}/landingLab.json</code>), key song song 2 file.</li><li>Nhóm key: <code>landingLab.stages.*</code>, <code>landingLab.apps.&lt;id&gt;.{category,title,diff1,diff2}</code>, <code>landingLab.banner.*</code>, <code>landingLab.&lt;screen&gt;.*</code>.</li><li>Không hardcode chuỗi hiển thị trong JSX; dữ liệu mẫu dạng mảng đọc bằng <code>returnObjects</code>.</li></ul><h2 id="light-dark-mode" tabindex="-1">Light/Dark mode <a class="header-anchor" href="#light-dark-mode" aria-label="Permalink to &quot;Light/Dark mode&quot;">​</a></h2><p>Cửa sổ app mô phỏng luôn ở giao diện sáng (giống hiện tại, vì nó là &quot;ảnh chụp&quot; app trên nền wallpaper). Không phụ thuộc theme site, nên đổi theme site không đổi màu bên trong cửa sổ. Chữ/nền đạt contrast WCAG AA trên nền trắng.</p><h2 id="edge-cases" tabindex="-1">Edge Cases <a class="header-anchor" href="#edge-cases" aria-label="Permalink to &quot;Edge Cases&quot;">​</a></h2><ul><li>Tab id không hợp lệ → về <code>overview</code>.</li><li>Đổi ngôn ngữ khi đang ở một tab → giữ tab, đổi chữ.</li><li><code>prefers-reduced-motion</code> → không chạy auto-demo.</li></ul><h2 id="definition-of-done" tabindex="-1">Definition of Done <a class="header-anchor" href="#definition-of-done" aria-label="Permalink to &quot;Definition of Done&quot;">​</a></h2><p><code>tsc -b</code> sạch, lint sạch trên file đổi, test.md pass trên trình duyệt ở MacBook + iPhone, vi + en.</p><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><p>Trang landing khác ngoài lab; mobile app; backend.</p>',22)])])}const u=a(o,[["render",r]]);export{g as __pageData,u as default};
